  const pageUpdates = [
    ['p1','Lịch buổi sáng trong tuần còn vài giờ cho manicure và pedicure. Anh chị nhắn dịch vụ cùng khung giờ thuận tiện, tiệm xác nhận lại trước khi giữ chỗ.',images.reception],
    ['p2','Quán nhận đơn mang đi buổi trưa. Anh chị nhắn số phần và giờ muốn lấy, tụi mình kiểm tra thời gian chuẩn bị rồi xác nhận lại.',images.restaurant],
    ['p3','Khách thích mẫu móng ngắn có thể gửi hình trước buổi hẹn. Tiệm cùng xem độ dài và màu dưới ánh sáng tại bàn trước khi bắt đầu.',images.blush],
    ['p4','Studio vừa sắp lại khu tư vấn để khách dễ trao đổi trước dịch vụ. Lịch đầu tiên vẫn dành thêm 15 phút, chị em nhắn trước giờ có thể đến nhé.',images.spa],
    ['p5','Cắt và sấy trong tuần có thể đặt trước qua tin nhắn. Anh chị gửi độ dài tóc hiện tại và kiểu tham khảo để studio giữ đủ thời gian.',images.barber],
    ['p6','Tiệm muốn gom đơn theo tháng có thể nhắn số lượng dùng trung bình. Cửa hàng kiểm tra tồn từng mã trước khi chuẩn bị, tránh thay bằng loại khác khi chưa trao đổi.',images.retail],
    ['p7','Lịch dặm mi cần xác nhận tình trạng bộ hiện tại. Chị em gửi ảnh rõ dưới ánh sáng ban ngày để Linh trao đổi thời gian dự kiến trước khi giữ giờ.',images.spa],
    ['p8','Quán có bàn hai người buổi sáng trong tuần. Anh chị nhắn giờ đến nếu muốn ngồi gần cửa sổ; quán xác nhận theo bàn đang trống.',images.cafe],
    ['p9','River xin chào cộng đồng Austin. Tiệm nhận lịch riêng cho Gel-X và nail art; gửi mẫu trước giúp tụi mình chuẩn bị đúng khung giờ.',images.blue],
    ['p9','Bộ móng ngắn nền hồng trong cho khách thích gọn khi đi làm. Màu trên ảnh có thể khác dưới ánh sáng tiệm, mình cùng xem bảng màu khi đến nhé.',images.blush],
    ['p9','Cuối tuần tiệm nhận lịch từ 9 giờ 30. Khách đặt hai dịch vụ liên tiếp nhắn trước để tiệm sắp đủ giờ, tránh phải chờ đổi bàn.',images.reception],
    ['p10','Garden mở từ 7 giờ sáng, có cà phê và món ăn nhẹ. Nhóm từ 6 người nhắn giờ đến để quán kiểm tra bàn trước khi xác nhận.',images.cafe],
    ['p10','Quán vừa sắp thêm góc ngồi yên tĩnh gần cửa sổ. Anh chị cần bàn làm việc buổi sáng có thể hỏi trước tình trạng bàn qua tin nhắn.',images.restaurant],
    ['p10','Đơn mang đi buổi trưa được chuẩn bị theo giờ nhận đã xác nhận. Anh chị báo số phần, món và thời gian muốn lấy để quầy sắp thứ tự.',images.cafe],
    ['p11','Cửa hàng nhận danh sách vật tư qua tin nhắn. Gửi kèm mã hoặc ảnh bao bì để tụi mình kiểm tra đúng loại trước khi giữ hàng.',images.retail],
    ['p11','Đơn lấy trong ngày cần xác nhận lại số lượng tại quầy. Món đang chờ về sẽ được ghi riêng, cửa hàng chỉ thay mã khi anh chị đồng ý.',images.retail],
    ['p11','Studio cần bổ sung vật tư cho cuối tuần nhắn trước từ thứ Năm nhé. Tụi mình gom danh sách, kiểm tra tồn và hẹn giờ nhận để anh chị đỡ chờ.',images.retail],
    ['p12','Bella nhận lịch cắt và sấy tại Westchase. Khách đến lần đầu gửi kiểu đang thích cùng khung giờ rảnh để studio trao đổi trước.',images.barber],
    ['p12','Tư vấn màu tóc cần ảnh tóc hiện tại dưới ánh sáng ban ngày. Studio xác nhận thời gian dự kiến sau khi trao đổi, mỗi lịch chỉ nhận một khách.',images.barber],
    ['p12','Thứ Năm studio có giờ hẹn sau 5 giờ chiều. Anh chị nhắn dịch vụ muốn làm để Bella kiểm tra lịch và giữ đủ thời gian.',images.barber]
  ];
