  const groupUpdates=[
    ['g1','question','Mai Nguyễn','Ai có xe đẩy spa ở Houston cho mình xin kích thước?','Mình cần hai xe rộng dưới 20 inch, ưu tiên có khóa bánh. Anh chị còn dư gửi ảnh thật và khu vực nhận nhé.','Houston, TX',null],
    ['g1','tip','Bright Nail Supply','Đo lối đi trước khi mang tủ mới về tiệm','Tiệm mình ghi cả kích thước cửa, hành lang và vị trí đặt tủ. Khi đi xem đồ cũ, mang thước theo để kiểm tra trước khi thuê xe chở.','Houston, TX',images.retail],
    ['g2','showcase','Hà Nguyễn','Bộ hồng nhũ cho khách muốn móng dài vừa','Mình giữ nền trong và nhũ nhẹ ở hai ngón. Khách muốn gọn khi làm việc nên chọn độ dài vừa, phần đá chỉ tập trung ở đầu móng.','Houston, TX',images.blush],
    ['g2','event','Linh Nguyễn','Thực hành hoa mảnh trên tip cùng nhóm nhỏ','Hẹn 10:00–12:00, mỗi người mang cọ liner và tip. Nhắn nhóm để nhận địa điểm, tối đa tám người để có thời gian trao đổi từng bài.','Houston, TX',images.workshop],
    ['group-houston','question','Kim Tuyen','Tiệm nào ở Bellaire còn nhận người hỗ trợ thứ Sáu?','Mình rảnh 9:00–18:00, làm được gel manicure và pedicure. Anh chị nhắn lịch, cách tính công và giờ nghỉ trước khi chốt nhé.','Houston, TX',null],
    ['group-houston','tip','BITCOIN NAIL BAR','Xác nhận dịch vụ trước khi xếp khách cho thợ hỗ trợ','Tiệm nhắn trước số lịch và loại dịch vụ để người nhận ca chuẩn bị. Đầu ca dành ít phút chỉ chỗ dụng cụ và cách ghi chú lịch.','Houston, TX',images.reception],
    ['group-dallas','showcase','Thảo Lê','Bộ cô dâu nền trong, đá nhỏ ở hai ngón','Khách gửi ảnh váy và nhẫn trước buổi thử. Mình giữ nền nhẹ, chụp cả bàn tay dưới ánh sáng cửa sổ để khách xem tổng thể.','Dallas, TX',images.bridal],
    ['group-dallas','question','Mây Beauty Studio','Anh chị thường giữ bao lâu giữa hai lịch khách mới?','Studio dành thêm thời gian tư vấn nhưng có hôm vẫn cần lâu hơn. Mình muốn nghe cách các tiệm xác nhận dịch vụ trước khi giữ giờ.','Dallas, TX',null],
    ['group-salon-owners','tip','Lotus Nails','Chia danh sách vật tư thành cần ngay và dự phòng','Cuối ca tụi mình ghi món sắp hết, cuối tuần mới gom đơn. Đồ chỉ dùng cho một lịch riêng được đánh dấu để tránh mua thêm ngoài nhu cầu.','Houston, TX',images.retail],
    ['group-salon-owners','poll','BITCOIN NAIL BAR','Anh chị thường chốt lịch tuần mới vào ngày nào?','Cùng chọn thời điểm thuận tiện để người trong tiệm có thời gian sắp việc riêng.','Houston, TX',null],
    ['group-restaurant','general','Saigon Kitchen','Ca trưa nhẹ hơn khi thống nhất người phụ trách bàn nhóm','Quán thử ghi số bàn và người nhận order trước giờ mở cửa. Khi khách đến đông, cả bếp và quầy biết nên hỏi ai nếu có thay đổi.','Houston, TX',images.restaurant],
    ['group-restaurant','question','Ngọc Phạm','Anh chị bàn giao đơn mang đi bằng giấy hay trên POS?','Mình đang học cách kiểm tra đủ món và ghi chú. Muốn nghe cách các quán hạn chế nhầm túi khi nhiều đơn cùng giờ.','Dallas, TX',null],
    ['group-austin','showcase','River Nails','Móng ngắn màu xanh cho khách đi làm','Khách thích đổi màu nhưng cần gọn khi gõ máy. Tiệm chọn vuông bo góc, sơn hai lớp mỏng và kiểm tra màu dưới ánh sáng tại bàn.','Austin, TX',images.blue],
    ['group-austin','event','Sally Thanh Hoang','Cà phê trao đổi cách sắp lịch hẹn tại North Austin','Hẹn nhóm nhỏ 9:00–10:00, mỗi người mang một ví dụ lịch tuần. Tự thanh toán đồ uống, nhắn nhóm để xác nhận địa điểm.','Austin, TX',images.cafe],
    ['group-lash-studio','tip','Linh Lash Studio','Hỏi trước khách có cần tháo bộ mi cũ không','Một câu xác nhận khi đặt hẹn giúp studio giữ đủ giờ. Mình cũng nhắn lại dịch vụ và thời gian dự kiến để khách sắp việc sau buổi hẹn.','Dallas, TX',images.spa],
    ['group-lash-studio','question','Mây Beauty Studio','Khách lần đầu thường gửi ảnh tham khảo qua đâu?','Studio nhận hình qua tin nhắn để chuẩn bị trước. Anh chị có cách sắp ảnh và ghi chú gọn theo từng lịch mà vẫn dễ tìm không?','Dallas, TX',null],
    ['group-new','question','Jessica Nguyen','Ngày đầu đến tiệm nên chuẩn bị dụng cụ gì?','Mình đã hỏi phần tiệm có sẵn, đang soạn lại túi cá nhân. Anh chị chia sẻ cách lập danh sách để khỏi mang quá nhiều đồ nhé.','Houston, TX',null],
    ['group-new','tip','David Le','Ghi lại dịch vụ đã quen để trao đổi lịch với tiệm','Mình chuẩn bị vài ảnh tự làm và ghi rõ kỹ thuật đang nhận được. Khi nói chuyện với tiệm, hai bên dễ chọn loại lịch phù hợp hơn.','Houston, TX',images.workshop],
    ['group-tax','general','Linh Nguyễn','Mình sắp hóa đơn theo từng tháng để dễ tìm lại','Cuối tuần mình gom giấy tờ vào thư mục theo tháng và ghi chú khoản chưa rõ. Trước buổi hẹn, mình gửi danh sách câu hỏi cho người làm thuế.','Dallas, TX',null],
    ['group-tax','question','Mai Nguyễn','Anh chị lưu bản chụp giấy tờ theo tháng hay theo loại?','Mình muốn sắp hồ sơ gọn trước khi gặp người phụ trách thuế. Chỉ hỏi cách lưu tài liệu, anh chị đừng đăng giấy tờ có thông tin cá nhân nhé.','Houston, TX',null],
    ['group-ai','tip','Bright Nail Supply','Bản nháp AI vẫn cần người kiểm tra thông tin sản phẩm','Cửa hàng dùng bản nháp để sắp ý, sau đó kiểm tra lại mã, số lượng và câu chữ. Không đưa thông tin đơn hàng của khách vào nội dung mẫu.','Houston, TX',images.retail],
    ['group-ai','question','Sally Thanh Hoang','Anh chị dùng AI để sắp danh sách việc trong tuần thế nào?','Mình đang thử nhóm việc theo buổi rồi tự xem lại lịch. Muốn nghe cách viết đầu vào ngắn mà không phải đưa thông tin riêng của khách.','Austin, TX',null],
    ['group-market-dallas','question','Thảo Lê','Tìm tủ sơn rộng dưới 36 inch quanh Richardson','Mình cần tủ gỗ sáng hoặc màu trắng, còn đủ kệ. Anh chị gửi ảnh, số đo và giá, mình có xe đến nhận vào cuối tuần.','Dallas, TX',null],
    ['group-market-dallas','tip','Studio Supply Dallas','Chụp cả chân và mặt dưới khi bán lại bàn cũ','Người xem dễ kiểm tra tình trạng hơn khi có ảnh các góc và số đo. Cửa hàng cũng ghi rõ món nào có thể tháo để vận chuyển.','Dallas, TX',images.marketTable],
    ['group-coffee','general','Garden Cafe','Quầy sáng chuẩn bị từ danh sách ngắn trước giờ mở cửa','Nhóm mình chia người kiểm tra ly, nguyên liệu và máy POS. Món nào thiếu được báo lại ngay, tránh đợi đến khi có khách mới đi tìm.','Houston, TX',images.cafe],
    ['group-coffee','poll','An Phạm','Ca sáng anh chị thường bàn giao quầy lúc mấy giờ?','Mình muốn biết khung giờ giao ca phổ biến để sắp lịch nhận hỗ trợ.','Austin, TX',null],
    ['group-hair','showcase','Bella Hair Room','Góc studio có ánh sáng tự nhiên cho buổi tư vấn','Studio giữ bàn ít đồ để khách dễ xem ảnh tham khảo. Mình xác nhận độ dài và dịch vụ trước khi bắt đầu mỗi lịch.','Houston, TX',images.barber],
    ['group-hair','question','An Hair Studio','Anh chị dành bao lâu cho lịch tư vấn đổi màu?','Khách thường gửi ảnh tóc hiện tại nhưng mình vẫn muốn có thời gian trao đổi trực tiếp. Anh chị chia sẻ cách giữ lịch cho buổi đầu nhé.','Austin, TX',null],
    ['group-supply','tip','Studio Supply Dallas','Ghi mã cùng số lượng giúp cửa hàng chuẩn bị đúng đơn','Tiệm gửi ảnh bao bì hoặc tên sản phẩm đang dùng. Cửa hàng xác nhận món còn hàng trước khi hẹn giờ lấy, không tự thay bằng mã khác.','Dallas, TX',images.retail],
    ['group-supply','question','Bright Nail Supply','Tiệm kiểm tra vật tư mỗi tuần vào đầu hay cuối ca?','Mình muốn thống nhất thời điểm để danh sách bổ sung sát với số lượng thực tế. Anh chị chia sẻ cách làm thuận tiện cho nhóm nhé.','Houston, TX',null],
    ['group-market-austin','general','River Nails','Tiệm có ghế chờ và đèn dự phòng đang để lại','Anh chị xem ảnh, giá và số lượng ở mục Mua bán. Tiệm hẹn xem trực tiếp tại Round Rock, được kiểm tra từng món trước khi lấy.','Austin, TX',images.marketChair],
    ['group-market-austin','question','An Phạm','Tìm bàn hai người cho góc cửa sổ tại quán','Cần ba bộ nhỏ, mặt dễ lau và chân chắc. Mình nhận quanh North Austin hoặc Round Rock, anh chị gửi kích thước và giá theo bộ nhé.','Austin, TX',null]
  ];
