  if (!baselines || typeof baselines !== 'object' || Array.isArray(baselines)) baselines = {};
  function merge(current, seeds, legacy = [], scope = '') {
    const validRow=row=>row&&typeof row==='object'&&!Array.isArray(row)&&typeof row.id==='string';
    const rows = Array.isArray(current) ? clone(current.filter(validRow)) : [];
    for(const row of rows){const timestamp=String(row.id||'').match(/^(?:extra|new)-(\d{13})/);if(!row.createdAt&&timestamp)row.createdAt=new Date(Number(timestamp[1])).toISOString();}
    const known = new Map(rows.map(row => [row.id, row]));
    const previous = new Map((Array.isArray(baselines[scope]) ? baselines[scope] : legacy).filter(validRow).map(row => [row.id, row]));
    for (const seed of seeds) {
      const row = known.get(seed.id);
      if (!row) { rows.push(clone(seed)); continue; }
      const before = previous.get(seed.id) || {};
      for (const [key, value] of Object.entries(seed)) {
        if(value===undefined)continue;
        if (row[key] === undefined || JSON.stringify(row[key]) === JSON.stringify(before[key])) row[key] = clone(value);
      }
    }
    baselines[scope] = clone(seeds);
    try { localStorage.setItem(baselineKey, JSON.stringify(baselines)); } catch {}
    return rows;
  }
